"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

QUERY = """query Settlements($after: String) {
  settlements(first: 100, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}"""

MAX_RETRIES = 10
MAX_TRAVERSALS = 5


def graphql(url, query, variables):
    """Send one GraphQL request, retrying a 429 after the server's delay."""
    body = json.dumps({"query": query, "variables": variables}).encode()
    attempt = 0
    while True:
        req = urllib.request.Request(
            url, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.load(resp)
            break
        except urllib.error.HTTPError as exc:
            if exc.code != 429 or attempt >= MAX_RETRIES:
                raise
            attempt += 1
            delay = exc.headers.get("Retry-After")
            try:
                delay = float(delay)
            except (TypeError, ValueError):
                delay = 1.0
            time.sleep(max(0.0, delay))
    if result.get("errors"):
        raise RuntimeError(result["errors"])
    return result["data"]


def traverse(url):
    """Page through every settlement, keyed by id so amendments keep the last version."""
    settlements = {}
    after = None
    while True:
        connection = graphql(url, QUERY, {"after": after})["settlements"]
        for settlement in connection["nodes"]:
            settlements[settlement["id"]] = settlement
        page_info = connection["pageInfo"]
        # A short or empty page does not mean the end; only hasNextPage does.
        if not page_info["hasNextPage"]:
            return settlements
        after = page_info["endCursor"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    url = f"{args.base_url.rstrip('/')}/v2/graphql"

    settlements = None
    for attempt in range(MAX_TRAVERSALS):
        try:
            settlements = traverse(url)
            break
        except RuntimeError:
            # A malformed or expired cursor returns a GraphQL error: start
            # the traversal again without `after`.
            if attempt + 1 >= MAX_TRAVERSALS:
                raise

    with open(args.out, "w") as f:
        for settlement in settlements.values():
            f.write(json.dumps(settlement) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

